/**
 * Wrap record fragments in the `PubmedArticleSet` envelope EFetch returns,
 * prolog and DOCTYPE included. Records appear in the order given, so a caller
 * can build a mixed set whose upstream order is known.
 */
export function articleSetXml(...records: string[]): string {
  return [
    '<?xml version="1.0" ?>',
    '<!DOCTYPE PubmedArticleSet PUBLIC "-//NLM//DTD PubMedArticle, 1st January 2025//EN" "https://dtd.nlm.nih.gov/ncbi/pubmed/out/pubmed_250101.dtd">',
    `<PubmedArticleSet>${records.join('')}</PubmedArticleSet>`,
  ].join('\n');
}

/** Parse an EFetch body through the production response handler. */
export function parseArticleSetXml(xml: string): XmlPubmedArticleSet {
  const parsed = new NcbiResponseHandler().parseAndHandleResponse<{
    PubmedArticleSet: XmlPubmedArticleSet;
  }>(xml, 'efetch', { retmode: 'xml' });
  return parsed.PubmedArticleSet;
}

/** Parse an ESummary body through the production response handler. */
export function parseESummaryXml(xml: string): ESummaryResult {
  const parsed = new NcbiResponseHandler().parseAndHandleResponse<{
    eSummaryResult: ESummaryResult;
  }>(xml, 'esummary', { retmode: 'xml' });
  return parsed.eSummaryResult;
}

